
-- CommandProject: weather, the interface part (generated by the launcher). Every quarter of a second
-- it finds the part of the map the camera shows (points of the ground projected on the screen) and,
-- when that changes, sends it to the simulation (SimCallback 'CPWeather'), which keeps the rain or
-- snow over that part only.

local CPWeatherThread = false

-- ground rectangle the main view shows: x0, z0, x1, z1 (nil when it cannot tell)
local function CPWeatherSample()
    local view = import('/lua/ui/game/worldview.lua').viewLeft
    if not view then return nil end
    local s = GetCamera('WorldCamera'):SaveSettings()
    local f, zoom = s.Focus, s.Zoom
    if not (f and zoom and zoom > 0) then return nil end
    local w, h = view.Width(), view.Height()
    local n, span = 12, 2.4 * zoom
    local step = 2 * span / n
    local x0, z0, x1, z1
    for i = 0, n do
        for j = 0, n do
            local px, pz = f[1] - span + i * step, f[3] - span + j * step
            local v = view:Project(Vector(px, f[2], pz))
            local sx, sy = v.x or v[1], v.y or v[2]
            if sx and sy and sx >= -0.1 * w and sx <= 1.1 * w and sy >= -0.1 * h and sy <= 1.1 * h then
                if not x0 then
                    x0, z0, x1, z1 = px, pz, px, pz
                else
                    x0, z0 = math.min(x0, px), math.min(z0, pz)
                    x1, z1 = math.max(x1, px), math.max(z1, pz)
                end
            end
        end
    end
    if not x0 then
        x0, z0, x1, z1 = f[1] - zoom, f[3] - zoom, f[1] + zoom, f[3] + zoom
    end
    -- the samples are a step apart: the view reaches up to a step beyond the last one inside
    return x0 - step, z0 - step, x1 + step, z1 + step
end

function CPWeatherUIStart()
    if CPWeatherThread then return end
    local info = SessionGetScenarioInfo()
    if not (info and info.Options and info.Options.CPWeather) then return end
    CPWeatherThread = ForkThread(function()
        local last = false
        while true do
            WaitSeconds(0.25)
            local ok, x0, z0, x1, z1 = pcall(CPWeatherSample)
            if ok and x0 then
                -- only when the view moved more than a tenth of its size (or changed size)
                local tol = math.max(4, 0.1 * math.min(x1 - x0, z1 - z0))
                if not last or math.abs(x0 - last[1]) > tol or math.abs(z0 - last[2]) > tol
                    or math.abs(x1 - last[3]) > tol or math.abs(z1 - last[4]) > tol then
                    last = { x0, z0, x1, z1 }
                    pcall(SimCallback, { Func = 'CPWeather', Args = { x0 = x0, z0 = z0, x1 = x1, z1 = z1 } })
                end
            end
        end
    end)
end

local CPWeatherCreateTimerDialog = CreateTimerDialog
function CreateTimerDialog(parent)
    CPWeatherCreateTimerDialog(parent)
    pcall(CPWeatherUIStart)
end
